define enum Status as
  Pending
  Running
end
fnc run(Status s): string {
  return match<string> s over
    on Status.Pending -> { return "p"; }
    on Status.Running -> { return "r"; }
  end;
}

define enum Event as
  Ping
  Stop
end
define pattern Input as
  Event | string
end
define actor Worker<messages=Input> as
  receive(Input m): void {
    do match m over
      on Event.Ping -> { }
      on Event.Stop -> { }
      on is string value -> { }
    end
  }
end

define enum Status as Ready end
define pattern Input as Status | string end
const x = Input.Ready;

define pattern Payload as string | int end
type Alias = Payload;
define enum Bad as Data(value: Alias) end

define enum State as On Off end
fnc label(State s): string {
  return match<string> s over
    on State.On -> { return "on"; }
  end;
}

define actor Worker as
  receive(ActorMail<string> msg): void { return; }
end
pub routine main(): void {
  const a = await spawn Worker();
  a.send("foo");
  return;
}

define actor Worker as
  receive(ActorMail<List<string>> msg): void { return; }
end
pub routine main(): void {
  const a = await spawn Worker();
  a.send(["a", "b"]);
  return;
}

define enum Event as
  Started(id: string) = "started"
  Stopped = "stopped"
end
define actor Worker<messages=Event> as
  receive(Event msg): void { return; }
end
pub routine main(): void {
  const a = await spawn Worker();
  a.send(Event.Started("id"));
  return;
}

define actor Worker as
  receive(ActorMail<string> msg): void { return; }
end
pub routine main(): void {
  const a = await spawn Worker();
  a.send(123);
  return;
}

define actor Worker as
  receive(ActorMail<ActorRef<Worker>> msg): void { return; }
end

define actor Worker as
  receive(ActorMail<ActorId> msg): void { return; }
end

define actor Worker as
  receive(ActorMail<List<ActorId>> msg): void { return; }
end
